  padding: 16px 0 10px 0;
}

.error-msg {
  color: #ff6464;
  margin-bottom: 10px;
  font-size: .98rem;
  font-weight: 500;
  text-align: center;
}

.loading-msg {
  color: var(--base-light);
  margin-bottom: 12px;
  font-size: .97rem;
  text-align: center;
