  display: flex;
  flex-direction: column;
  align-items: stretch;
}

.todo-form {
  display: flex;
  margin-bottom: 26px;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 10px 14px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: #181d2b;
  color: var(--text-color);
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.todo-input:focus {
  border-color: var(--base-light);
}

