  margin: 140px auto 0 auto;
  background: rgba(255,255,255,0.03);
  padding: 32px 28px 24px 28px;
  border-radius: 14px;
  box-shadow: 0 4px 16px 0 rgba(0,0,0,0.06);
  display: flex;
  flex-direction: column;
  align-items: stretch;
}

.todo-form {
  display: flex;
  margin-bottom: 26px;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 10px 14px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: #181d2b;
  color: var(--text-color);
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.todo-input:focus {
  border-color: var(--base-light);
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  min-height: 40px;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255,255,255,0.05);
  padding: 10px 12px;
  border-radius: 6px;
  margin-bottom: 8px;
  font-size: 1.07rem;
}

.todo-title {
  flex: 1;
  word-break: break-word;
}

.btn-delete {
  background: none;
  color: var(--base-light);
  border: none;
  font-size: 1.20rem;
  cursor: pointer;
  padding: 6px 7px;
  margin-left: 8px;
  border-radius: 4px;
  transition: background 0.18s;
}

.btn-delete:hover,
.btn-delete:focus {
  background: rgba(0,255,255,0.13);
}

.todo-empty {
  text-align: center;
  color: var(--text-secondary);
  font-size: 1.01rem;
  padding: 16px 0 10px 0;
}

.error-msg {
  color: #ff6464;
  margin-bottom: 10px;
  font-size: .98rem;
  font-weight: 500;
  text-align: center;
}

.loading-msg {
  color: var(--base-light);
  margin-bottom: 12px;
  font-size: .97rem;
  text-align: center;
